                   (x == max(x_coords) and y == min(y_coords)):
                    print(moves * 2)
                    break
                if x < max(x_coords):
                    new_x = x + 1
                    if (new_x, y) not in visited:
                        queue.append((new_x, y))
                        visited.add((new_x, y))
                if x > min(x_coords):
                    new_x = x - 1
                    if (new_x, y) not in visited:
                        queue.append((new_x, y))
                        visited.add((new_x, y))
                if y < max(y_coords):
                    new_y = y + 1
                    if (x, new_y) not in visited:
                        queue.append((x, new_y))
                        visited.add((x, new_y))
                if y > min(y_coords):
                    new_y = y - 1
                    if (x, new_y) not in visited:
